package com.skillmasterai.modules.feedback;

/**
 * One image or short video attached to a feedback document, as M18 stores it (v65).
 *
 * <p>{@code sha256} is the server's digest of the stored bytes and {@code mediaType} is what the
 * server detected from the file header — neither is trusted from the client. {@code objectKey} is
 * generated by {@link FeedbackAttachmentSafety#objectKey}; it contains a ULID and never the
 * original filename or the feedback receipt.
 *
 * @param position zero-based order the attachments were submitted in
 * @param filename the basename after control characters are removed; display only
 */
public record FeedbackAttachment(
        String id,
        String feedbackId,
        int position,
        String filename,
        String mediaType,
        long sizeBytes,
        String sha256,
        String objectKey,
        String createdAt) {
}
